//! CDK wallet ⇄ Spilman channel integration tests over the C ABI.
//!
//! These tests are fully offline. They drive the exported `cdk_*` functions
//! from Zig exactly as the application does, using deterministic wire fixtures
//! generated by `vendor/cdk-wallet-ffi/src/fixtures.rs` for the parts that
//! normally need a mint (blind signatures + NUT-12 DLEQ over the blinded
//! outputs).
//!
//! Coverage is split into three groups:
//!
//! * contract tests: keyset/token JSON shapes, fee math, determinism, argument
//!   validation, secret redaction, ABI layout;
//! * handoff tests: a CDK token becomes Spilman parameters, CDK wallet helpers
//!   fail closed on unapproved mints, balance-update and close-swap structure;
//! * replay tests: real mint responses are unblinded into a verified channel,
//!   split at close, claimed by both parties, and refunded after expiry.
const std = @import("std");
const cdk = @import("cdk");

const c = cdk.c;
const fixture_text = @embedFile("testdata/spilman_vectors.json");

/// Parsed fixture document. All slices point into the arena.
const Fx = struct {
    arena: std.heap.ArenaAllocator,
    root: std.json.Value,

    fn init(alloc: std.mem.Allocator) !Fx {
        var arena = std.heap.ArenaAllocator.init(alloc);
        const root = try std.json.parseFromSliceLeaky(
            std.json.Value,
            arena.allocator(),
            fixture_text,
            .{},
        );
        return .{ .arena = arena, .root = root };
    }

    fn deinit(self: *Fx) void {
        self.arena.deinit();
    }

    fn text(self: *Fx, key: []const u8) []const u8 {
        return self.root.object.get(key).?.string;
    }

    fn int(self: *Fx, key: []const u8) u64 {
        return @intCast(self.root.object.get(key).?.integer);
    }

    fn responseText(self: *Fx, key: []const u8, alloc: std.mem.Allocator) ![]u8 {
        const responses = self.root.object.get("responses").?.object;
        return std.json.Stringify.valueAlloc(alloc, responses.get(key).?, .{});
    }
};

fn freeError(err: ?[*:0]u8) void {
    if (err) |e| c.cdk_string_free(e);
}

fn freeString(value: [*c]u8) void {
    if (value != null) c.cdk_string_free(value);
}

/// Duplicate a Zig string as a NUL-terminated C string.
fn z(alloc: std.mem.Allocator, s: []const u8) ![:0]u8 {
    return alloc.dupeSentinel(u8, s, 0);
}

fn spanString(value: [*c]u8) []const u8 {
    return std.mem.span(@as([*:0]const u8, @ptrCast(value)));
}

/// Copy a Rust-owned string result, free the original, and assert success.
fn takeString(alloc: std.mem.Allocator, result: c.CdkStringResult_t) ![]u8 {
    defer freeError(result.@"error");
    if (result.status != c.CDK_STATUS_OK) {
        std.debug.print(
            "unexpected status {d}: {s}\n",
            .{ result.status, if (result.@"error" != null) spanString(result.@"error") else "" },
        );
        return error.UnexpectedStatus;
    }
    try std.testing.expect(result.value != null);
    const copy = try alloc.dupe(u8, spanString(result.value));
    c.cdk_string_free(result.value);
    return copy;
}

/// Assert a string result failed with `status` and return a copy of the error.
fn expectErr(alloc: std.mem.Allocator, result: c.CdkStringResult_t, status: c.CdkStatus_t) ![]u8 {
    if (result.status != status) {
        std.debug.print(
            "expected status {d}, got {d}: {s}\n",
            .{ status, result.status, if (result.@"error" != null) spanString(result.@"error") else "" },
        );
        return error.UnexpectedStatus;
    }
    try std.testing.expect(result.@"error" != null);
    const message = try alloc.dupe(u8, spanString(result.@"error"));
    defer c.cdk_string_free(result.@"error");
    freeString(result.value);
    return message;
}

fn expectStatusOk(result: c.CdkStatusResult_t) !void {
    defer freeError(result.@"error");
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), result.status);
}

fn expectStatusErr(
    alloc: std.mem.Allocator,
    result: c.CdkStatusResult_t,
    status: c.CdkStatus_t,
) ![]u8 {
    try std.testing.expectEqual(status, result.status);
    try std.testing.expect(result.@"error" != null);
    const message = try alloc.dupe(u8, spanString(result.@"error"));
    defer c.cdk_string_free(result.@"error");
    return message;
}

fn expectNoLeak(haystack: []const u8, needle: []const u8) !void {
    if (std.mem.indexOf(u8, haystack, needle) != null) {
        std.debug.print("error message leaked {s}: {s}\n", .{ needle, haystack });
        return error.SecretLeaked;
    }
}

fn isHex(s: []const u8) bool {
    for (s) |ch| if (!std.ascii.isHex(ch)) return false;
    return true;
}

const CloseProofs = struct {
    receiver: []u8,
    sender: []u8,
    receiver_sum: u64,
    sender_sum: u64,
};

fn takeClose(alloc: std.mem.Allocator, result: c.CdkSpilmanCloseResult_t) !CloseProofs {
    defer freeError(result.@"error");
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), result.status);
    try std.testing.expect(result.receiver_proofs_json != null);
    try std.testing.expect(result.sender_proofs_json != null);
    const receiver = try alloc.dupe(u8, spanString(result.receiver_proofs_json));
    const sender = try alloc.dupe(u8, spanString(result.sender_proofs_json));
    c.cdk_string_free(result.receiver_proofs_json);
    c.cdk_string_free(result.sender_proofs_json);
    return .{
        .receiver = receiver,
        .sender = sender,
        .receiver_sum = result.receiver_sum,
        .sender_sum = result.sender_sum,
    };
}

fn expectCloseErr(alloc: std.mem.Allocator, result: c.CdkSpilmanCloseResult_t, status: c.CdkStatus_t) ![]u8 {
    try std.testing.expectEqual(status, result.status);
    try std.testing.expect(result.@"error" != null);
    const message = try alloc.dupe(u8, spanString(result.@"error"));
    defer c.cdk_string_free(result.@"error");
    freeString(result.receiver_proofs_json);
    freeString(result.sender_proofs_json);
    return message;
}

const Tamper = enum { flip_c, drop_signature, change_amount, flip_e };

/// Mutate a mint `SwapResponse` in one specific way.
fn tamperResponse(alloc: std.mem.Allocator, text: []const u8, mode: Tamper) ![]u8 {
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const a = arena.allocator();
    var parsed = try std.json.parseFromSliceLeaky(std.json.Value, a, text, .{});
    const signatures = parsed.object.getPtr("signatures").?;
    switch (mode) {
        .flip_c => {
            const value = signatures.array.items[0].object.getPtr("C_").?;
            const bytes = try a.dupe(u8, value.string);
            bytes[bytes.len - 1] = if (bytes[bytes.len - 1] == '0') '1' else '0';
            value.* = .{ .string = bytes };
        },
        .drop_signature => {
            signatures.array.shrinkRetainingCapacity(signatures.array.items.len - 1);
        },
        .change_amount => {
            const value = signatures.array.items[0].object.getPtr("amount").?;
            value.* = .{ .integer = value.integer * 2 };
        },
        .flip_e => {
            const value = signatures.array.items[0].object.getPtr("dleq").?.object.getPtr("e").?;
            const bytes = try a.dupe(u8, value.string);
            bytes[bytes.len - 1] = if (bytes[bytes.len - 1] == '0') '1' else '0';
            value.* = .{ .string = bytes };
        },
    }
    return std.json.Stringify.valueAlloc(alloc, parsed, .{});
}

/// Build a funding swap, feed it the fixture's mint response, and return the
/// resulting funding proofs JSON.
fn fundFromFixture(
    alloc: std.mem.Allocator,
    params: [:0]const u8,
    secret: [:0]const u8,
    keyset: [:0]const u8,
    response_text: []const u8,
) ![]u8 {
    const funding = try takeString(alloc, c.cdk_spilman_create_funding_swap(
        params,
        secret,
        keyset,
        @as([*:0]const u8, "[]"),
    ));
    defer alloc.free(funding);
    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, funding, .{});
    defer parsed.deinit();
    const funding_secrets = try z(alloc, parsed.value.object.get("funding_secrets_json").?.string);
    defer alloc.free(funding_secrets);
    const response_z = try z(alloc, response_text);
    defer alloc.free(response_z);

    const completed = try takeString(alloc, c.cdk_spilman_complete_funding_swap(
        response_z,
        funding_secrets,
        keyset,
    ));
    defer alloc.free(completed);
    const completed_json = try std.json.parseFromSlice(std.json.Value, alloc, completed, .{});
    defer completed_json.deinit();
    return alloc.dupe(u8, completed_json.value.object.get("funding_proofs_json").?.string);
}

/// Build a keyset JSON document with a chosen spelling and key order.
fn keysetJson(
    alloc: std.mem.Allocator,
    fx: *Fx,
    snake: bool,
    reverse: bool,
    fee: u64,
) ![]u8 {
    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, fx.text("keyset_json"), .{});
    defer parsed.deinit();
    const keys = parsed.value.object.get("keys").?.object;

    const k1 = keys.get("1").?.string;
    const k2 = keys.get("2").?.string;
    const k4 = keys.get("4").?.string;
    const k8 = keys.get("8").?.string;
    const k16 = keys.get("16").?.string;
    const k32 = keys.get("32").?.string;
    const k64 = keys.get("64").?.string;

    const id_key = if (snake) "keyset_id" else "keysetId";
    const fee_key = if (snake) "input_fee_ppk" else "inputFeePpk";
    if (reverse) {
        return std.fmt.allocPrint(
            alloc,
            "{{\"{s}\":\"{s}\",\"unit\":\"sat\",\"keys\":{{" ++
                "\"64\":\"{s}\",\"32\":\"{s}\",\"16\":\"{s}\",\"8\":\"{s}\"," ++
                "\"4\":\"{s}\",\"2\":\"{s}\",\"1\":\"{s}\"}}," ++
                "\"amounts\":[64,32,16,8,4,2,1],\"{s}\":{d}}}",
            .{ id_key, fx.text("keyset_id"), k64, k32, k16, k8, k4, k2, k1, fee_key, fee },
        );
    }
    return std.fmt.allocPrint(
        alloc,
        "{{\"{s}\":\"{s}\",\"unit\":\"sat\",\"keys\":{{" ++
            "\"1\":\"{s}\",\"2\":\"{s}\",\"4\":\"{s}\",\"8\":\"{s}\"," ++
            "\"16\":\"{s}\",\"32\":\"{s}\",\"64\":\"{s}\"}}," ++
            "\"amounts\":[64,32,16,8,4,2,1],\"{s}\":{d}}}",
        .{ id_key, fx.text("keyset_id"), k1, k2, k4, k8, k16, k32, k64, fee_key, fee },
    );
}

fn testWalletPath(tmp: *std.testing.TmpDir, buf: []u8) [:0]const u8 {
    const prefix = ".zig-cache/tmp/";
    const suffix = "/wallet.sqlite";
    var i: usize = 0;
    @memcpy(buf[i..][0..prefix.len], prefix);
    i += prefix.len;
    @memcpy(buf[i..][0..tmp.sub_path.len], &tmp.sub_path);
    i += tmp.sub_path.len;
    @memcpy(buf[i..][0..suffix.len], suffix);
    i += suffix.len;
    buf[i] = 0;
    return buf[0..i :0];
}

// ---------------------------------------------------------------------------
// Tier 0: contracts, edges, ABI, redaction
// ---------------------------------------------------------------------------

test "spilman keyset JSON accepts snake_case, camelCase, and unordered keys" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);

    const variants = [_]struct { snake: bool, reverse: bool }{
        .{ .snake = true, .reverse = false },
        .{ .snake = false, .reverse = false },
        .{ .snake = true, .reverse = true },
        .{ .snake = false, .reverse = true },
    };

    var expected: ?[]u8 = null;
    defer if (expected) |e| alloc.free(e);
    for (variants) |variant| {
        const keyset = try keysetJson(alloc, &fx, variant.snake, variant.reverse, 0);
        defer alloc.free(keyset);
        const keyset_z = try z(alloc, keyset);
        defer alloc.free(keyset_z);

        const id = try takeString(alloc, c.cdk_spilman_channel_parameters_get_channel_id(
            params,
            secret,
            keyset_z,
        ));
        defer alloc.free(id);
        try std.testing.expectEqual(@as(usize, 64), id.len);
        if (expected) |e| {
            try std.testing.expectEqualStrings(e, id);
        } else {
            expected = try alloc.dupe(u8, id);
        }

        const funding = c.cdk_spilman_compute_funding_token_amount(100, keyset_z, 64);
        defer freeError(funding.@"error");
        try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), funding.status);
        try std.testing.expectEqual(@as(u64, 100), funding.net_sats);
    }
}

test "spilman funding amount covers capacity plus input fees" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const fee0 = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(fee0);
    const fee1000 = try keysetJson(alloc, &fx, true, false, 999);
    defer alloc.free(fee1000);
    const fee0_z = try z(alloc, fee0);
    defer alloc.free(fee0_z);
    const fee1000_z = try z(alloc, fee1000);
    defer alloc.free(fee1000_z);

    // (capacity, nominal at 0 ppk, nominal at 999 ppk), mirrored from the
    // Rust-side `funding_amount_vectors` regression test.
    const vectors = [_][3]u64{
        .{ 0, 0, 0 },
        .{ 1, 1, 4 },
        .{ 2, 2, 6 },
        .{ 3, 3, 6 },
        .{ 4, 4, 8 },
        .{ 5, 5, 10 },
        .{ 6, 6, 10 },
        .{ 7, 7, 10 },
        .{ 100, 100, 108 },
    };
    for (vectors) |vector| {
        const no_fee = c.cdk_spilman_compute_funding_token_amount(vector[0], fee0_z, 64);
        defer freeError(no_fee.@"error");
        try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), no_fee.status);
        try std.testing.expectEqual(vector[1], no_fee.net_sats);

        const with_fee = c.cdk_spilman_compute_funding_token_amount(vector[0], fee1000_z, 64);
        defer freeError(with_fee.@"error");
        try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), with_fee.status);
        try std.testing.expectEqual(vector[2], with_fee.net_sats);
    }

    // A zero-capacity channel needs no funding at all.
    const zero = c.cdk_spilman_compute_funding_token_amount(0, fee0_z, 64);
    defer freeError(zero.@"error");
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), zero.status);
    try std.testing.expectEqual(@as(u64, 0), zero.net_sats);
}

test "spilman channel id is deterministic and binds params, keyset, and secret" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);

    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const id = try takeString(alloc, c.cdk_spilman_channel_parameters_get_channel_id(
        params,
        secret,
        keyset_z,
    ));
    defer alloc.free(id);
    try std.testing.expectEqual(@as(usize, 64), id.len);
    try std.testing.expect(isHex(id));

    const repeat = try takeString(alloc, c.cdk_spilman_channel_parameters_get_channel_id(
        params,
        secret,
        keyset_z,
    ));
    defer alloc.free(repeat);
    try std.testing.expectEqualStrings(id, repeat);

    // Changing one bound input changes the id. The expiry is part of the
    // canonical parameter encoding, so a stale params document cannot be
    // replayed under a different expiry.
    const later = try std.mem.replaceOwned(
        u8,
        alloc,
        fx.text("params_json"),
        "\"expiry_timestamp\":1800000000",
        "\"expiry_timestamp\":1800000001",
    );
    defer alloc.free(later);
    const later_z = try z(alloc, later);
    defer alloc.free(later_z);
    const later_id = try takeString(alloc, c.cdk_spilman_channel_parameters_get_channel_id(
        later_z,
        secret,
        keyset_z,
    ));
    defer alloc.free(later_id);
    try std.testing.expect(!std.mem.eql(u8, id, later_id));

    // A different shared secret also changes the id.
    const kp = c.cdk_spilman_generate_keypair();
    defer freeError(kp.@"error");
    defer c.cdk_string_free(kp.secret_key_hex);
    defer c.cdk_string_free(kp.pubkey_hex);
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), kp.status);
    const other_secret = try takeString(alloc, c.cdk_spilman_compute_channel_secret(
        kp.secret_key_hex,
        kp.pubkey_hex,
    ));
    defer alloc.free(other_secret);
    const other_z = try z(alloc, other_secret);
    defer alloc.free(other_z);
    const other_id = try takeString(alloc, c.cdk_spilman_channel_parameters_get_channel_id(
        params,
        other_z,
        keyset_z,
    ));
    defer alloc.free(other_id);
    try std.testing.expect(!std.mem.eql(u8, id, other_id));
}

test "spilman funding outputs are deterministic for a fixed channel" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const alice = try z(alloc, fx.text("alice_secret"));
    defer alloc.free(alice);

    const first = try takeString(alloc, c.cdk_spilman_create_funding_outputs(
        params,
        alice,
        keyset_z,
    ));
    defer alloc.free(first);
    const second = try takeString(alloc, c.cdk_spilman_create_funding_outputs(
        params,
        alice,
        keyset_z,
    ));
    defer alloc.free(second);
    try std.testing.expectEqualStrings(first, second);

    // A different channel secret derives different blinded messages.
    const kp = c.cdk_spilman_generate_keypair();
    defer freeError(kp.@"error");
    defer c.cdk_string_free(kp.secret_key_hex);
    defer c.cdk_string_free(kp.pubkey_hex);
    const other_secret = try takeString(alloc, c.cdk_spilman_compute_channel_secret(
        alice.ptr,
        kp.pubkey_hex,
    ));
    defer alloc.free(other_secret);
    const other_secret_z = try z(alloc, other_secret);
    defer alloc.free(other_secret_z);
    const other_swap = try takeString(alloc, c.cdk_spilman_create_funding_swap(
        params,
        other_secret_z,
        keyset_z,
        @as([*:0]const u8, "[]"),
    ));
    defer alloc.free(other_swap);
    try std.testing.expect(!std.mem.eql(u8, first, other_swap));
}

test "spilman verify_valid_channel never echoes proof secrets" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);

    // Same counts/amounts as the expected deterministic outputs, but with
    // attacker-chosen secrets, so `SecretMismatch` fires with the raw values.
    const proofs = try std.fmt.allocPrint(
        alloc,
        "[{{\"amount\":64,\"id\":\"{s}\",\"secret\":\"LEAKME-64\",\"C\":\"{s}\"}}," ++
            "{{\"amount\":32,\"id\":\"{s}\",\"secret\":\"LEAKME-32\",\"C\":\"{s}\"}}," ++
            "{{\"amount\":4,\"id\":\"{s}\",\"secret\":\"LEAKME-4\",\"C\":\"{s}\"}}]",
        .{
            fx.text("keyset_id"), fx.text("alice_pubkey"),
            fx.text("keyset_id"), fx.text("alice_pubkey"),
            fx.text("keyset_id"), fx.text("alice_pubkey"),
        },
    );
    defer alloc.free(proofs);
    const proofs_z = try z(alloc, proofs);
    defer alloc.free(proofs_z);

    const message = try expectStatusErr(
        alloc,
        c.cdk_spilman_verify_valid_channel(params, secret, keyset_z, proofs_z),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(message);
    try std.testing.expect(std.mem.indexOf(u8, message, "SecretMismatch") != null);
    try expectNoLeak(message, "LEAKME");
    try expectNoLeak(message, fx.text("channel_secret"));
}

test "spilman rejects malformed hex and JSON without echoing inputs" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);

    const kp = c.cdk_spilman_generate_keypair();
    defer freeError(kp.@"error");
    defer c.cdk_string_free(kp.secret_key_hex);
    defer c.cdk_string_free(kp.pubkey_hex);
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), kp.status);
    const secret = spanString(kp.secret_key_hex);
    const public = spanString(kp.pubkey_hex);

    // Empty and wrong-length keys: no panic, stable status, no echo.
    const empty = try expectErr(
        alloc,
        c.cdk_spilman_secret_key_to_pubkey(@as([*:0]const u8, "")),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(empty);

    const short = try z(alloc, secret[0 .. secret.len - 1]);
    defer alloc.free(short);
    const short_err = try expectErr(
        alloc,
        c.cdk_spilman_secret_key_to_pubkey(short),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(short_err);

    const long = try std.fmt.allocPrintSentinel(alloc, "{s}00", .{secret}, 0);
    defer alloc.free(long);
    const long_err = try expectErr(
        alloc,
        c.cdk_spilman_secret_key_to_pubkey(long),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(long_err);
    try expectNoLeak(long_err, secret);

    const non_hex = try z(alloc, "zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz");
    defer alloc.free(non_hex);
    const non_hex_err = try expectErr(
        alloc,
        c.cdk_spilman_secret_key_to_pubkey(non_hex),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(non_hex_err);

    // A 33-byte tweak and a 31-byte digest are structurally invalid.
    const message = @as([*:0]const u8, "00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff");
    const wide_tweak = try z(alloc, "010101010101010101010101010101010101010101010101010101010101010101");
    defer alloc.free(wide_tweak);
    const wide_err = try expectErr(
        alloc,
        c.cdk_spilman_sign_with_tweaked_key_util(kp.secret_key_hex, message, wide_tweak),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(wide_err);

    const short_message = try z(alloc, "00112233445566778899aabbccddeeff00112233445566778899aabbccddee");
    defer alloc.free(short_message);
    const short_msg_err = try expectErr(
        alloc,
        c.cdk_spilman_sign_with_tweaked_key_util(
            kp.secret_key_hex,
            short_message,
            @as([*:0]const u8, "0101010101010101010101010101010101010101010101010101010101010101"),
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(short_msg_err);

    // An invalid public key is rejected, and the key text is not echoed.
    const bad_pub = try z(alloc, "deadbeef");
    defer alloc.free(bad_pub);
    const bad_pub_err = try expectErr(
        alloc,
        c.cdk_spilman_compute_channel_secret(kp.secret_key_hex, bad_pub),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(bad_pub_err);
    try expectNoLeak(bad_pub_err, "deadbeef");

    // Malformed JSON never reaches parsing past the boundary.
    const json_err = try expectErr(
        alloc,
        c.cdk_spilman_create_funding_outputs(
            @as([*:0]const u8, "{"),
            kp.secret_key_hex,
            keyset_z,
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(json_err);

    // NULL required arguments are reported distinctly.
    const null_result = c.cdk_spilman_secret_key_to_pubkey(null);
    defer freeError(null_result.@"error");
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_NULL_ARGUMENT), null_result.status);
    try std.testing.expect(public.len == 66);
}

test "cashuB round-trip preserves witness and p2pk_e" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const mint = try z(alloc, fx.text("mint_url"));
    defer alloc.free(mint);

    const signature = try z(
        alloc,
        "1111111111111111111111111111111111111111111111111111111111111111" ++
            "2222222222222222222222222222222222222222222222222222222222222222",
    );
    defer alloc.free(signature);
    const proofs = try std.fmt.allocPrint(
        alloc,
        "[{{\"amount\":4,\"id\":\"{s}\",\"secret\":\"stage2-secret\"," ++
            "\"C\":\"{s}\",\"p2pk_e\":\"{s}\"," ++
            "\"witness\":\"{{\\\"signatures\\\":[\\\"{s}\\\"]}}\"}}]",
        .{
            fx.text("keyset_id"),
            fx.text("alice_pubkey"),
            fx.text("charlie_pubkey"),
            signature,
        },
    );
    defer alloc.free(proofs);
    const proofs_z = try z(alloc, proofs);
    defer alloc.free(proofs_z);

    const token = try takeString(alloc, c.cdk_spilman_build_cashu_b_token(
        mint,
        @as([*:0]const u8, "sat"),
        proofs_z,
    ));
    defer alloc.free(token);
    try std.testing.expect(std.mem.startsWith(u8, token, "cashuB"));

    const token_z = try z(alloc, token);
    defer alloc.free(token_z);
    const decoded = try takeString(alloc, c.cdk_token_to_proofs_json(token_z, keyset_z));
    defer alloc.free(decoded);

    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, decoded, .{});
    defer parsed.deinit();
    const items = parsed.value.array.items;
    try std.testing.expectEqual(@as(usize, 1), items.len);
    const proof = items[0].object;
    try std.testing.expectEqual(@as(i64, 4), proof.get("amount").?.integer);
    try std.testing.expectEqualStrings("stage2-secret", proof.get("secret").?.string);
    try std.testing.expectEqualStrings(
        fx.text("charlie_pubkey"),
        proof.get("p2pk_e").?.string,
    );
    const decoded_witness = try std.json.parseFromSlice(
        std.json.Value,
        alloc,
        proof.get("witness").?.string,
        .{},
    );
    defer decoded_witness.deinit();
    try std.testing.expectEqualStrings(
        signature,
        decoded_witness.value.object.get("signatures").?.array.items[0].string,
    );

    // V3 (`cashuA`) is accepted by the same decoder; the proof value survives.
    const legacy = try takeString(alloc, c.cdk_spilman_build_cashu_a_token(mint, proofs_z));
    defer alloc.free(legacy);
    const legacy_z = try z(alloc, legacy);
    defer alloc.free(legacy_z);
    const legacy_decoded = try takeString(alloc, c.cdk_token_to_proofs_json(legacy_z, keyset_z));
    defer alloc.free(legacy_decoded);
    try std.testing.expect(std.mem.indexOf(u8, legacy_decoded, "\"secret\"") != null);

    // Malformed keyset metadata is rejected instead of being trusted.
    const malformed = try expectErr(
        alloc,
        c.cdk_token_to_proofs_json(token_z, @as([*:0]const u8, "{")),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(malformed);
}

test "wallet Spilman helpers fail closed on unapproved mints" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [std.fs.max_path_bytes]u8 = undefined;
    const path = testWalletPath(&tmp, &path_buf);

    const seed: [64]u8 = @splat(21);
    const opened = c.cdk_wallet_open(cdk.byteSlice(&seed), path.ptr);
    defer c.cdk_recovery_reports_free(opened.reports);
    defer freeError(opened.@"error");
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_OK), opened.status);
    const handle = opened.handle;
    defer _ = c.cdk_wallet_close(handle);

    const mint = try z(alloc, fx.text("mint_url"));
    defer alloc.free(mint);
    const keyset_id = try z(alloc, fx.text("keyset_id"));
    defer alloc.free(keyset_id);

    // Read helpers check the allowlist before touching the network.
    const active = c.cdk_wallet_get_active_keyset_info_json(handle, mint);
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_MINT_NOT_REGISTERED), active.status);
    defer freeError(active.@"error");
    freeString(active.value);

    const keyset = c.cdk_wallet_get_keyset_info_json(handle, mint, keyset_id);
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_MINT_NOT_REGISTERED), keyset.status);
    defer freeError(keyset.@"error");
    freeString(keyset.value);

    // An unparseable keyset id is rejected even before the allowlist check.
    const bad_id = c.cdk_wallet_get_keyset_info_json(handle, mint, @as([*:0]const u8, "nope"));
    defer freeError(bad_id.@"error");
    freeString(bad_id.value);
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_INVALID_ARGUMENT), bad_id.status);

    // State-changing helpers are guarded identically, even with junk payloads.
    const swap = c.cdk_wallet_post_swap(handle, mint, @as([*:0]const u8, "{}"));
    defer freeError(swap.@"error");
    freeString(swap.value);
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_MINT_NOT_REGISTERED), swap.status);

    const proofs = c.cdk_wallet_receive_proofs(handle, mint, @as([*:0]const u8, "[]"), null);
    defer freeError(proofs.@"error");
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_MINT_NOT_REGISTERED), proofs.status);

    // A well-formed token for the same unapproved mint is still refused.
    const funding_proofs = try z(alloc, fx.text("funding_proofs_json"));
    defer alloc.free(funding_proofs);
    const token = try takeString(alloc, c.cdk_spilman_build_cashu_b_token(
        mint,
        @as([*:0]const u8, "sat"),
        funding_proofs,
    ));
    defer alloc.free(token);
    const token_z = try z(alloc, token);
    defer alloc.free(token_z);
    // Token-driven receives report the token's (unapproved) mint specifically.
    const received = c.cdk_wallet_receive_with_keys(handle, token_z, null);
    defer freeError(received.@"error");
    try std.testing.expectEqual(@as(c.CdkStatus_t, c.CDK_STATUS_TOKEN_UNKNOWN_MINT), received.status);
}

test "spilman ABI result structs match the C header layout" {
    const Keypair = c.CdkSpilmanKeypairResult_t;
    const Close = c.CdkSpilmanCloseResult_t;

    try std.testing.expect(@typeInfo(Keypair).@"struct".layout == .@"extern");
    try std.testing.expect(@typeInfo(Close).@"struct".layout == .@"extern");
    try std.testing.expectEqual(@as(u16, 8), @bitSizeOf(c.CdkStatus_t));
    try std.testing.expectEqual(@as(usize, 0), @offsetOf(Keypair, "status"));
    try std.testing.expectEqual(@as(usize, 0), @offsetOf(Close, "status"));
    try std.testing.expect(@offsetOf(Keypair, "error") > @offsetOf(Keypair, "status"));
    try std.testing.expect(@offsetOf(Keypair, "secret_key_hex") > @offsetOf(Keypair, "error"));
    try std.testing.expect(@offsetOf(Keypair, "pubkey_hex") > @offsetOf(Keypair, "secret_key_hex"));
    try std.testing.expect(@offsetOf(Close, "receiver_sum") > @offsetOf(Close, "sender_proofs_json"));
    try std.testing.expectEqual(
        @offsetOf(Close, "receiver_sum") + @sizeOf(u64),
        @offsetOf(Close, "sender_sum"),
    );
    try std.testing.expect(@offsetOf(Close, "receiver_sum") % @alignOf(u64) == 0);
}

