test "cdk token to spilman channel parameters bridge" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const mint = try z(alloc, fx.text("mint_url"));
    defer alloc.free(mint);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);
    const alice_pub = try z(alloc, fx.text("alice_pubkey"));
    defer alloc.free(alice_pub);
    const charlie_pub = try z(alloc, fx.text("charlie_pubkey"));
    defer alloc.free(charlie_pub);

    const proofs = try z(alloc, fx.text("funding_proofs_json"));
    defer alloc.free(proofs);
    const token = try takeString(alloc, c.cdk_spilman_build_cashu_b_token(
        mint,
        @as([*:0]const u8, "sat"),
        proofs,
    ));
    defer alloc.free(token);
    const token_z = try z(alloc, token);
    defer alloc.free(token_z);

    const expiry = fx.int("expiry_timestamp");
    const computed = try takeString(alloc, c.cdk_spilman_compute_channel_from_token(
        token_z,
        charlie_pub,
        alice_pub,
        secret,
        expiry,
        keyset_z,
        64,
    ));
    defer alloc.free(computed);

    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, computed, .{});
    defer parsed.deinit();
    const obj = parsed.value.object;
    try std.testing.expectEqual(
        fx.int("funding_token_amount"),
        @as(u64, @intCast(obj.get("capacity").?.integer)),
    );

    // The returned proofs are the CDK proofs embedded in the token.
    const returned_proofs = obj.get("proofs_json").?.string;
    const proof_values = try std.json.parseFromSlice(std.json.Value, alloc, returned_proofs, .{});
    defer proof_values.deinit();
    var total: u64 = 0;
    for (proof_values.value.array.items) |proof| {
        total += @intCast(proof.object.get("amount").?.integer);
    }
    try std.testing.expectEqual(fx.int("funding_token_amount"), total);

    // The returned parameters are complete and canonical enough to derive the
    // channel id, and the id is bound to the expiry.
    const returned_params = obj.get("params_json").?.string;
    try std.testing.expect(std.mem.indexOf(u8, returned_params, fx.text("mint_url")) != null);
    try std.testing.expect(std.mem.indexOf(u8, returned_params, "\"unit\":\"sat\"") != null);

    const params_z = try z(alloc, returned_params);
    defer alloc.free(params_z);
    const id = try takeString(alloc, c.cdk_spilman_channel_parameters_get_channel_id(
        params_z,
        secret,
        keyset_z,
    ));
    defer alloc.free(id);
    const id_again = try takeString(alloc, c.cdk_spilman_channel_parameters_get_channel_id(
        params_z,
        secret,
        keyset_z,
    ));
    defer alloc.free(id_again);
    try std.testing.expectEqualStrings(id, id_again);

    const later = try takeString(alloc, c.cdk_spilman_compute_channel_from_token(
        token_z,
        charlie_pub,
        alice_pub,
        secret,
        expiry + 1,
        keyset_z,
        64,
    ));
    defer alloc.free(later);
    const later_parsed = try std.json.parseFromSlice(std.json.Value, alloc, later, .{});
    defer later_parsed.deinit();
    const later_params = try z(alloc, later_parsed.value.object.get("params_json").?.string);
    defer alloc.free(later_params);
    const later_id = try takeString(alloc, c.cdk_spilman_channel_parameters_get_channel_id(
        later_params,
        secret,
        keyset_z,
    ));
    defer alloc.free(later_id);
    try std.testing.expect(!std.mem.eql(u8, id, later_id));
}

test "cdk token to spilman applies input fees and rejects junk tokens" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const fee1000 = try keysetJson(alloc, &fx, true, false, 999);
    defer alloc.free(fee1000);
    const fee1000_z = try z(alloc, fee1000);
    defer alloc.free(fee1000_z);
    const mint = try z(alloc, fx.text("mint_url"));
    defer alloc.free(mint);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);
    const alice_pub = try z(alloc, fx.text("alice_pubkey"));
    defer alloc.free(alice_pub);
    const charlie_pub = try z(alloc, fx.text("charlie_pubkey"));
    defer alloc.free(charlie_pub);

    const proofs = try z(alloc, fx.text("funding_proofs_json"));
    defer alloc.free(proofs);
    const token = try takeString(alloc, c.cdk_spilman_build_cashu_b_token(
        mint,
        @as([*:0]const u8, "sat"),
        proofs,
    ));
    defer alloc.free(token);
    const token_z = try z(alloc, token);
    defer alloc.free(token_z);

    // Three input proofs at 999 ppk cost 3 sats (stage 1: 100 -> 97); the 97
    // funding token then splits into 64+32+1 and costs another 5 sats to spend
    // (stage 2), leaving 89 sats of usable capacity.
    const computed = try takeString(alloc, c.cdk_spilman_compute_channel_from_token(
        token_z,
        charlie_pub,
        alice_pub,
        secret,
        fx.int("expiry_timestamp"),
        fee1000_z,
        64,
    ));
    defer alloc.free(computed);
    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, computed, .{});
    defer parsed.deinit();
    try std.testing.expectEqual(@as(i64, 89), parsed.value.object.get("capacity").?.integer);

    // Junk tokens are rejected without a panic.
    const junk = try expectErr(
        alloc,
        c.cdk_spilman_compute_channel_from_token(
            @as([*:0]const u8, "cashuBnot-a-token"),
            charlie_pub,
            alice_pub,
            secret,
            fx.int("expiry_timestamp"),
            fee1000_z,
            64,
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(junk);
}

test "spilman balance updates sign, verify, tamper, and replay" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);
    const alice = try z(alloc, fx.text("alice_secret"));
    defer alloc.free(alice);
    const proofs = try z(alloc, fx.text("funding_proofs_json"));
    defer alloc.free(proofs);

    // A signed update verifies.
    const signed = try takeString(alloc, c.cdk_spilman_create_signed_balance_update(
        params,
        keyset_z,
        alice,
        proofs,
        30,
    ));
    defer alloc.free(signed);
    const signed_json = try std.json.parseFromSlice(std.json.Value, alloc, signed, .{});
    defer signed_json.deinit();
    const signature = signed_json.value.object.get("signature").?.string;
    const channel_id = signed_json.value.object.get("channel_id").?.string;
    const signature_z = try z(alloc, signature);
    defer alloc.free(signature_z);
    const channel_id_z = try z(alloc, channel_id);
    defer alloc.free(channel_id_z);

    try expectStatusOk(c.cdk_spilman_verify_balance_update(
        params,
        secret,
        keyset_z,
        proofs,
        channel_id_z,
        30,
        signature_z,
    ));

    // The three-step unsigned flow produces a verifiable update too.
    const unsigned = try takeString(alloc, c.cdk_spilman_create_unsigned_balance_update(
        params,
        keyset_z,
        secret,
        proofs,
        70,
    ));
    defer alloc.free(unsigned);
    const unsigned_json = try std.json.parseFromSlice(std.json.Value, alloc, unsigned, .{});
    defer unsigned_json.deinit();
    const unsigned_swap = try z(
        alloc,
        unsigned_json.value.object.get("unsigned_swap_request_json").?.string,
    );
    defer alloc.free(unsigned_swap);
    const unsigned_msg = try z(alloc, unsigned_json.value.object.get("message_hex").?.string);
    defer alloc.free(unsigned_msg);
    const unsigned_tweak = try z(
        alloc,
        unsigned_json.value.object.get("tweak_scalar_hex").?.string,
    );
    defer alloc.free(unsigned_tweak);
    const unsigned_id = try z(alloc, unsigned_json.value.object.get("channel_id").?.string);
    defer alloc.free(unsigned_id);

    const manual_signature = try takeString(alloc, c.cdk_spilman_sign_with_tweaked_key_util(
        alice,
        unsigned_msg,
        unsigned_tweak,
    ));
    defer alloc.free(manual_signature);
    const manual_signature_z = try z(alloc, manual_signature);
    defer alloc.free(manual_signature_z);
    const attached = try takeString(alloc, c.cdk_spilman_attach_signature_to_balance_update(
        unsigned_swap,
        manual_signature_z,
        unsigned_id,
        70,
    ));
    defer alloc.free(attached);
    const attached_json = try std.json.parseFromSlice(std.json.Value, alloc, attached, .{});
    defer attached_json.deinit();
    const attached_signature = try z(
        alloc,
        attached_json.value.object.get("signature").?.string,
    );
    defer alloc.free(attached_signature);

    try expectStatusOk(c.cdk_spilman_verify_balance_update(
        params,
        secret,
        keyset_z,
        proofs,
        unsigned_id,
        70,
        attached_signature,
    ));

    // Replay semantics: an older, still-validly-signed balance is accepted.
    // The application must persist the highest balance it has seen.
    try expectStatusOk(c.cdk_spilman_verify_balance_update(
        params,
        secret,
        keyset_z,
        proofs,
        channel_id_z,
        30,
        signature_z,
    ));

    // A balance above capacity, a wrong channel id, and a tampered signature
    // are all rejected locally.
    const over = try expectStatusErr(
        alloc,
        c.cdk_spilman_verify_balance_update(
            params,
            secret,
            keyset_z,
            proofs,
            channel_id_z,
            fx.int("funding_token_amount") + 1,
            signature_z,
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(over);

    const wrong_id = try expectStatusErr(
        alloc,
        c.cdk_spilman_verify_balance_update(
            params,
            secret,
            keyset_z,
            proofs,
            @as([*:0]const u8, "0011111111111111"),
            30,
            signature_z,
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(wrong_id);

    const tampered = try alloc.dupe(u8, signature);
    defer alloc.free(tampered);
    tampered[tampered.len - 1] = if (tampered[tampered.len - 1] == '0') '1' else '0';
    const tampered_z = try z(alloc, tampered);
    defer alloc.free(tampered_z);
    const tampered_err = try expectStatusErr(
        alloc,
        c.cdk_spilman_verify_balance_update(
            params,
            secret,
            keyset_z,
            proofs,
            channel_id_z,
            30,
            tampered_z,
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(tampered_err);
}

test "spilman close swap request carries two signatures and validates the receiver key" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);
    const alice = try z(alloc, fx.text("alice_secret"));
    defer alloc.free(alice);
    const charlie = try z(alloc, fx.text("charlie_secret"));
    defer alloc.free(charlie);
    const proofs = try z(alloc, fx.text("funding_proofs_json"));
    defer alloc.free(proofs);

    const balance = fx.int("close_balance");
    const update = try takeString(alloc, c.cdk_spilman_create_signed_balance_update(
        params,
        keyset_z,
        alice,
        proofs,
        balance,
    ));
    defer alloc.free(update);
    const update_json = try std.json.parseFromSlice(std.json.Value, alloc, update, .{});
    defer update_json.deinit();
    const sender_signature = try z(alloc, update_json.value.object.get("signature").?.string);
    defer alloc.free(sender_signature);

    const prepared = try takeString(alloc, c.cdk_spilman_prepare_close_swap(
        params,
        secret,
        keyset_z,
        keyset_z,
        proofs,
        balance,
        sender_signature,
        charlie,
    ));
    defer alloc.free(prepared);
    const prepared_json = try std.json.parseFromSlice(std.json.Value, alloc, prepared, .{});
    defer prepared_json.deinit();
    const obj = prepared_json.value.object;

    const sig_all = obj.get("sig_all_message_hash").?.string;
    try std.testing.expectEqual(@as(usize, 64), sig_all.len);
    try std.testing.expect(isHex(sig_all));

    // The funding proofs are the swap inputs; only the first input carries the
    // two SIG_ALL witnesses (sender then receiver), each a 64-byte signature.
    const swap = obj.get("swap_request").?.object;
    const inputs = swap.get("inputs").?.array.items;
    try std.testing.expectEqual(@as(usize, 3), inputs.len);
    for (inputs, 0..) |input, index| {
        const witness = input.object.get("witness");
        if (index == 0) {
            try std.testing.expect(witness != null);
            // NUT-11 witnesses are serialized as a JSON string.
            const parsed_witness = try std.json.parseFromSlice(
                std.json.Value,
                alloc,
                witness.?.string,
                .{},
            );
            defer parsed_witness.deinit();
            const signatures = parsed_witness.value.object.get("signatures").?.array.items;
            try std.testing.expectEqual(@as(usize, 2), signatures.len);
            for (signatures) |sig| try std.testing.expectEqual(@as(usize, 128), sig.string.len);
        } else {
            try std.testing.expect(witness == null);
        }
    }

    // The commitment secrets cover the expected post-stage-1 total.
    const secrets = obj.get("secrets_with_blinding").?.array.items;
    var secret_total: u64 = 0;
    for (secrets) |entry| secret_total += @intCast(entry.object.get("amount").?.integer);
    try std.testing.expectEqual(obj.get("expected_total").?.integer, @as(i64, @intCast(secret_total)));

    // A receiver key that is not the channel receiver is rejected locally
    // instead of producing a swap the mint will refuse.
    const other = c.cdk_spilman_generate_keypair();
    defer freeError(other.@"error");
    defer c.cdk_string_free(other.secret_key_hex);
    defer c.cdk_string_free(other.pubkey_hex);
    const other_err = try expectErr(
        alloc,
        c.cdk_spilman_prepare_close_swap(
            params,
            secret,
            keyset_z,
            keyset_z,
            proofs,
            balance,
            sender_signature,
            other.secret_key_hex,
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(other_err);
    try std.testing.expect(std.mem.indexOf(u8, other_err, "does not match") != null);

    // A balance above capacity is rejected.
    const over = try expectErr(
        alloc,
        c.cdk_spilman_prepare_close_swap(
            params,
            secret,
            keyset_z,
            keyset_z,
            proofs,
            fx.int("funding_token_amount") + 1,
            sender_signature,
            charlie,
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(over);

    // A tampered sender signature is rejected before the receiver co-signs.
    const tampered = try alloc.dupe(u8, sender_signature);
    defer alloc.free(tampered);
    tampered[tampered.len - 1] = if (tampered[tampered.len - 1] == '0') '1' else '0';
    const tampered_z = try z(alloc, tampered);
    defer alloc.free(tampered_z);
    const tampered_err = try expectErr(
        alloc,
        c.cdk_spilman_prepare_close_swap(
            params,
            secret,
            keyset_z,
            keyset_z,
            proofs,
            balance,
            tampered_z,
            charlie,
        ),
        c.CDK_STATUS_INVALID_ARGUMENT,
    );
    defer alloc.free(tampered_err);
}

