test "fixture: funding swap completes into a verified channel" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);

    const response = try fx.responseText("funding", alloc);
    defer alloc.free(response);
    const funding_proofs = try fundFromFixture(alloc, params, secret, keyset_z, response);
    defer alloc.free(funding_proofs);
    const funding_z = try z(alloc, funding_proofs);
    defer alloc.free(funding_z);

    // The replayed proofs are byte-identical to the fixture: the blinding,
    // DLEQ, and deterministic secret derivation all still line up.
    try std.testing.expectEqualStrings(fx.text("funding_proofs_json"), funding_proofs);

    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, funding_proofs, .{});
    defer parsed.deinit();
    var total: u64 = 0;
    for (parsed.value.array.items) |proof| total += @intCast(proof.object.get("amount").?.integer);
    try std.testing.expectEqual(fx.int("funding_token_amount"), total);

    // The receiver's channel verification (keyset id, DLEQ, totals,
    // deterministic secrets) accepts the completed funding proofs.
    try expectStatusOk(c.cdk_spilman_verify_valid_channel(params, secret, keyset_z, funding_z));
}

test "fixture: cooperative close splits 70/30 and signs the receiver" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);
    const alice = try z(alloc, fx.text("alice_secret"));
    defer alloc.free(alice);
    const charlie = try z(alloc, fx.text("charlie_secret"));
    defer alloc.free(charlie);

    const funding_response = try fx.responseText("funding", alloc);
    defer alloc.free(funding_response);
    const funding_proofs = try fundFromFixture(alloc, params, secret, keyset_z, funding_response);
    defer alloc.free(funding_proofs);
    const funding_z = try z(alloc, funding_proofs);
    defer alloc.free(funding_z);

    const balance = fx.int("close_balance");
    const update = try takeString(alloc, c.cdk_spilman_create_signed_balance_update(
        params,
        keyset_z,
        alice,
        funding_z,
        balance,
    ));
    defer alloc.free(update);
    const update_json = try std.json.parseFromSlice(std.json.Value, alloc, update, .{});
    defer update_json.deinit();
    const sender_signature = try z(alloc, update_json.value.object.get("signature").?.string);
    defer alloc.free(sender_signature);

    const prepared = try takeString(alloc, c.cdk_spilman_prepare_close_swap(
        params,
        secret,
        keyset_z,
        keyset_z,
        funding_z,
        balance,
        sender_signature,
        charlie,
    ));
    defer alloc.free(prepared);
    const prepared_json = try std.json.parseFromSlice(std.json.Value, alloc, prepared, .{});
    defer prepared_json.deinit();
    const secrets_json = try std.json.Stringify.valueAlloc(
        alloc,
        prepared_json.value.object.get("secrets_with_blinding").?,
        .{},
    );
    defer alloc.free(secrets_json);
    const secrets_z = try z(alloc, secrets_json);
    defer alloc.free(secrets_z);

    const response = try fx.responseText("close", alloc);
    defer alloc.free(response);
    const response_z = try z(alloc, response);
    defer alloc.free(response_z);

    const closed = try takeClose(alloc, c.cdk_spilman_unblind_close_swap(
        params,
        secret,
        keyset_z,
        keyset_z,
        secrets_z,
        response_z,
        balance,
        charlie,
    ));
    defer alloc.free(closed.receiver);
    defer alloc.free(closed.sender);

    try std.testing.expectEqual(balance, closed.receiver_sum);
    try std.testing.expectEqual(fx.int("funding_token_amount") - balance, closed.sender_sum);

    // The receiver's proofs are stage-2 P2PK-locked and pre-signed with the
    // tweaked key, so Charlie can claim them with an ordinary wallet receive.
    const receiver = try std.json.parseFromSlice(std.json.Value, alloc, closed.receiver, .{});
    defer receiver.deinit();
    try std.testing.expect(receiver.value.array.items.len > 0);
    for (receiver.value.array.items) |proof| {
        try std.testing.expect(proof.object.get("p2pk_e") != null);
        const witness = try std.json.parseFromSlice(
            std.json.Value,
            alloc,
            proof.object.get("witness").?.string,
            .{},
        );
        defer witness.deinit();
        const signatures = witness.value.object.get("signatures").?.array.items;
        try std.testing.expectEqual(@as(usize, 1), signatures.len);
        try std.testing.expectEqual(@as(usize, 128), signatures[0].string.len);
    }

    // The sender's proofs only carry `p2pk_e` (NUT-28 P2BK): Alice derives the
    // key when she claims them, so no witness is attached here.
    const sender = try std.json.parseFromSlice(std.json.Value, alloc, closed.sender, .{});
    defer sender.deinit();
    try std.testing.expect(sender.value.array.items.len > 0);
    for (sender.value.array.items) |proof| {
        try std.testing.expect(proof.object.get("p2pk_e") != null);
        const witness = proof.object.get("witness");
        try std.testing.expect(witness == null);
    }
}

test "fixture: tampered swap responses are rejected" {
    const alloc = std.testing.allocator;
    var fx = try Fx.init(alloc);
    defer fx.deinit();

    const keyset = try keysetJson(alloc, &fx, true, false, 0);
    defer alloc.free(keyset);
    const keyset_z = try z(alloc, keyset);
    defer alloc.free(keyset_z);
    const params = try z(alloc, fx.text("params_json"));
    defer alloc.free(params);
    const secret = try z(alloc, fx.text("channel_secret"));
    defer alloc.free(secret);
    const alice = try z(alloc, fx.text("alice_secret"));
    defer alloc.free(alice);
    const charlie = try z(alloc, fx.text("charlie_secret"));
    defer alloc.free(charlie);

    const funding_response = try fx.responseText("funding", alloc);
    defer alloc.free(funding_response);
    const funding_proofs = try fundFromFixture(alloc, params, secret, keyset_z, funding_response);
    defer alloc.free(funding_proofs);
    const funding_z = try z(alloc, funding_proofs);
    defer alloc.free(funding_z);

    const balance = fx.int("close_balance");
    const update = try takeString(alloc, c.cdk_spilman_create_signed_balance_update(
        params,
        keyset_z,
        alice,
        funding_z,
        balance,
    ));
    defer alloc.free(update);
    const update_json = try std.json.parseFromSlice(std.json.Value, alloc, update, .{});
    defer update_json.deinit();
    const sender_signature = try z(alloc, update_json.value.object.get("signature").?.string);
    defer alloc.free(sender_signature);

    const prepared = try takeString(alloc, c.cdk_spilman_prepare_close_swap(
        params,
        secret,
        keyset_z,
        keyset_z,
        funding_z,
        balance,
        sender_signature,
        charlie,
    ));
    defer alloc.free(prepared);
    const prepared_json = try std.json.parseFromSlice(std.json.Value, alloc, prepared, .{});
    defer prepared_json.deinit();
    const secrets_json = try std.json.Stringify.valueAlloc(
        alloc,
        prepared_json.value.object.get("secrets_with_blinding").?,
        .{},
    );
    defer alloc.free(secrets_json);
    const secrets_z = try z(alloc, secrets_json);
    defer alloc.free(secrets_z);

    const response = try fx.responseText("close", alloc);
    defer alloc.free(response);

    // Corrupting the blind signature, dropping one, changing an amount, or
    // flipping the DLEQ challenge must all be rejected, never partially
    // unblinded.
    const modes = [_]Tamper{ .flip_c, .drop_signature, .change_amount, .flip_e };
    for (modes) |mode| {
        const tampered = try tamperResponse(alloc, response, mode);
        defer alloc.free(tampered);
        const tampered_z = try z(alloc, tampered);
        defer alloc.free(tampered_z);
        const message = try expectCloseErr(
            alloc,
            c.cdk_spilman_unblind_close_swap(
                params,
                secret,
                keyset_z,
                keyset_z,
                secrets_z,
                tampered_z,
                balance,
                charlie,
            ),
            c.CDK_STATUS_INVALID_ARGUMENT,
        );
        defer alloc.free(message);
        // Proof secrets are bearer material and must not be echoed back.
        try expectNoLeak(message, "p2pk");
    }
}

