    defer alloc.free(alice);

    const funding_response = try fx.responseText("funding_expired", alloc);
    defer alloc.free(funding_response);
    const funding_proofs = try fundFromFixture(alloc, expired, secret, keyset_z, funding_response);
    defer alloc.free(funding_proofs);
    const funding_z = try z(alloc, funding_proofs);
    defer alloc.free(funding_z);

    const now = fx.int("refund_now");
    const prepared = try takeString(alloc, c.cdk_spilman_prepare_sender_refund(
        expired,
        secret,
        keyset_z,
        keyset_z,
        funding_z,
        alice,
        now,
        null,
    ));
    defer alloc.free(prepared);
    const prepared_z = try z(alloc, prepared);
