    defer alloc.free(refunded);

    const proofs = try std.json.parseFromSlice(std.json.Value, alloc, refunded, .{});
    defer proofs.deinit();
    var total: u64 = 0;
    for (proofs.value.array.items) |proof| total += @intCast(proof.object.get("amount").?.integer);
    try std.testing.expectEqual(fx.int("funding_token_amount"), total);

    // Before the expiry the refund path stays closed.
